private string message = "";

private async Task SaveAsync()
{
    var response = await Http.PostAsJsonAsync("api/todos", newTodo);

    if (response.IsSuccessStatusCode)
    {
        message = "Saved!";
    }
    else
    {
        message = "Save failed.";
    }
}

